import { test, expect, type Page } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, inviteAndJoin } from './helpers';

// [Verifier] NOTE: the snake's food cell is placed via Math.random(), so a
// real score change can't be produced deterministically through pure key
// input alone. We pin Math.random() from inside the already-loaded page
// (never touching app source) so the next food spawn(s) land at known grid
// cells, then drive the snake there with arrow keys.
async function pinNextFoodSpawns(page: Page, randomValues: number[]) {
  await page.evaluate((values) => {
    let i = 0;
    const orig = Math.random.bind(Math);
    Math.random = () => (i < values.length ? values[i++] : orig());
  }, randomValues);
}

async function waitForHeadAt(page: Page, targetIdx: number) {
  await page.waitForFunction(
    (target) => {
      const cells = document.querySelectorAll('[data-testid="snake-grid"] i');
      for (let idx = 0; idx < cells.length; idx++) {
        if (cells[idx].classList.contains('head')) return idx === target;
      }
      return false;
    },
    targetIdx,
    { timeout: 5_000 },
  );
}

/** Starts a fresh game and eats exactly one food pinned at grid cell (0,0),
 *  growing score by 10; the snake then runs into the wall on its own right
 *  after, ending the game (best-ever score += 10 net-new for this player). */
async function playOneFood(page: Page) {
  await pinNextFoodSpawns(page, [0, 0.999]);
  await page.getByTestId('start-game-btn').click();
  await page.keyboard.press('ArrowUp');
  await waitForHeadAt(page, 7); // row 0, column 7
  await page.keyboard.press('ArrowLeft');
  await waitForHeadAt(page, 0); // (0,0) -- eats the pinned food, score +10
}

/** Starts a fresh game and eats two foods pinned at (0,0) then (0,1),
 *  scoring +20 total, without ending the game (so the score jump reports
 *  while the run is still "playing" -- best-ever score only rises with it). */
async function playTwoFoods(page: Page) {
  // Exactly two food spawns happen before the second bite: reset()'s initial
  // placement (pin -> index 0) and the respawn triggered by eating that first
  // food (pin -> index 15, i.e. (0,1)). The previous 4-value pin array left
  // the respawn landing on index 224 instead of 15, so the ArrowDown move
  // below never actually ate a second food and the test's expected +20
  // score never materialized.
  await pinNextFoodSpawns(page, [0, 0.07]);
  await page.getByTestId('start-game-btn').click();
  await page.keyboard.press('ArrowUp');
  await waitForHeadAt(page, 7); // row 0, column 7
  await page.keyboard.press('ArrowLeft');
  await waitForHeadAt(page, 0); // (0,0) -- eats first food, score +10
  await page.keyboard.press('ArrowDown');
  await waitForHeadAt(page, 15); // (0,1) -- eats second food, score +20 total
}

test.describe(`player: see an all-time leaderboard with everyone's best-ever score`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`the leaderboard always lists every player with their highest recorded score, ordered best first`, async ({ browser }) => {
    test.setTimeout(60_000);
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await inviteAndJoin(pageA, pageB);

    // Give A a nonzero score so the ranking has more than one distinct value
    // to actually order.
    await playOneFood(pageA);

    await pageB.getByTestId('tab-leaderboard').click();
    await expect(pageB.getByTestId('item-player_status').first()).toBeVisible({ timeout: 10_000 });

    const scores = await pageB.getByTestId('item-player_status').evaluateAll((rows) =>
      rows.map((r) => Number(r.querySelector('.score')?.textContent ?? '0')),
    );
    expect(scores.length).toBeGreaterThanOrEqual(2);
    for (let i = 1; i < scores.length; i++) {
      expect(scores[i - 1]).toBeGreaterThanOrEqual(scores[i]);
    }

    await ctxA.close();
    await ctxB.close();
  });

  test(`a player's best score updates on the leaderboard whenever they beat their previous best, in any game or duel`, async ({ page }) => {
    test.setTimeout(60_000);
    await createWorkspace(page);
    await page.getByTestId('tab-leaderboard').click();

    // [Verifier] NOTE: identifies this player's own row via MemberLabel's
    // "(you)" badge, which every self row carries -- avoids depending on
    // display-name text, which varies per identity/session.
    const ownRow = page.getByTestId('item-player_status').filter({ hasText: '(you)' });
    await expect(ownRow).toBeVisible({ timeout: 10_000 });
    const readScore = async () => Number((await ownRow.locator('.score').textContent()) ?? '0');

    // Best score is monotonic and shared with earlier test runs against the
    // same persistent identity, so compare relative to whatever it already
    // is rather than asserting an absolute value.
    const before = await readScore();

    await page.getByTestId('tab-game').click();
    await playOneFood(page);
    await page.getByTestId('tab-leaderboard').click();
    const afterFirst = Math.max(before, 10);
    await expect(ownRow.locator('.score')).toHaveText(String(afterFirst), { timeout: 10_000 });

    // A second, higher-scoring run must push the recorded best up again.
    await page.getByTestId('tab-game').click();
    await playTwoFoods(page);
    await page.getByTestId('tab-leaderboard').click();
    const afterSecond = Math.max(afterFirst, 20);
    await expect(ownRow.locator('.score')).toHaveText(String(afterSecond), { timeout: 10_000 });
  });
});
